func:
// Normaliza o payload recebido da Bancada Smart 4.0 para o formato
// de linha do CSV (dados_producao.csv), conforme o Documento do Projeto:
// timestamp,bancada_id,status_operacional,pecas_boas,pecas_defeituosas,tempo_ciclo_segundos

const payload = msg.payload;

if (!payload || typeof payload !== 'object') {
    node.warn('Payload MQTT inválido, descartando mensagem.');
    return null;
}

const timestamp = payload.timestamp || new Date().toISOString();
const bancadaId = payload.bancada_id || 'BANCADA_SMART_01';
const statusOperacional = payload.status_operacional || 'DESCONHECIDO';
const pecasBoas = Number.isFinite(payload.pecas_boas) ? payload.pecas_boas : 0;
const pecasDefeituosas = Number.isFinite(payload.pecas_defeituosas) ? payload.pecas_defeituosas : 0;
const tempoCiclo = Number.isFinite(payload.tempo_ciclo_segundos) ? payload.tempo_ciclo_segundos : 0;

// Validação mínima: descarta leituras sem status operacional reconhecido
const statusValidos = ['EM_PRODUCAO', 'PARADA', 'MANUTENCAO', 'DESCONHECIDO'];
if (!statusValidos.includes(statusOperacional)) {
    node.warn(`status_operacional inválido: ${statusOperacional}`);
    return null;
}

const linhaCsv = [
    timestamp,
    bancadaId,
    statusOperacional,
    pecasBoas,
    pecasDefeituosas,
    tempoCiclo
].join(',');

msg.payload = linhaCsv + '\n';
msg.dadosEstruturados = {
    timestamp,
    bancada_id: bancadaId,
    status_operacional: statusOperacional,
    pecas_boas: pecasBoas,
    pecas_defeituosas: pecasDefeituosas,
    tempo_ciclo_segundos: tempoCiclo
};

return msg;

// Atualiza apenas o status atual da máquina na tabela estrutural.
// Uso opcional, conforme seção 5.1 do Documento do Projeto
// ("Nó PostgreSQL (opcional): atualiza o status atual da máquina").

const dados = msg.dadosEstruturados;

msg.topic = 'UPDATE techmob.maquina SET status_atual = $1, atualizado_em = NOW() WHERE bancada_id = $2';
msg.payload = [dados.status_operacional, dados.bancada_id];

return msg;
